<template><main class="page"><header><div><p class="eyebrow">STAGE 26 TRUSTED ECONOMY</p><h1>行星级情报韧性</h1><p>跨组织证明、后量子信任、离线协作和危机自治经济的统一控制面。</p></div><el-button :icon="Refresh" circle title="刷新" :loading="loading" @click="load"/></header><section class="metrics"><div v-for="item in metrics" :key="item.key"><span>{{item.label}}</span><strong>{{overview[item.key]??0}}</strong></div></section><el-tabs v-model="tab"><el-tab-pane label="信任与宪法" name="trust"><section class="grid"><article v-for="item in trust" :key="item.title"><el-icon><component :is="item.icon"/></el-icon><h2>{{item.title}}</h2><p>{{item.text}}</p><el-tag :type="item.type" effect="plain">{{item.state}}</el-tag></article></section></el-tab-pane><el-tab-pane label="行星孪生" name="twin"><section class="form"><h2>运行五域联合冲击</h2><el-checkbox-group v-model="domains"><el-checkbox v-for="domain in allDomains" :key="domain" :value="domain">{{domain}}</el-checkbox></el-checkbox-group><el-button type="primary" :icon="DataAnalysis" @click="runTwin">运行演练</el-button><div v-if="lastScore!==null" class="result"><span>系统性级联分数</span><strong>{{lastScore}}</strong></div></section></el-tab-pane><el-tab-pane label="自治经济" name="economy"><section class="grid"><article><el-icon><Goods/></el-icon><h2>危机资源交易</h2><p>优先级配给、交付、退款与结算全程守恒。</p></article><article><el-icon><Umbrella/></el-icon><h2>自治保险</h2><p>连续风险信号驱动保费、限额、准备金和自动赔付。</p></article><article><el-icon><View/></el-icon><h2>公共利益审计</h2><p>风险、公平性、资源分配与外部性提供公开承诺。</p></article></section></el-tab-pane></el-tabs></main></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{Connection,DataAnalysis,DocumentChecked,Goods,Key,Refresh,Umbrella,View}from'@element-plus/icons-vue';import{ElMessage}from'element-plus';import{planetaryResilienceApi}from'@/api/planetaryResilience';const loading=ref(false),tab=ref('trust'),overview=reactive<Record<string,number>>({}),allDomains=['energy','communications','logistics','finance','information'],domains=ref([...allDomains]),lastScore=ref<number|null>(null);const metrics=computed(()=>[{key:'proof_mesh',label:'证明网格'},{key:'policy_registry',label:'策略注册'},{key:'pq_migrations',label:'后量子迁移'},{key:'twin_runs',label:'孪生演练'},{key:'blocked_constitutions',label:'宪法阻断'},{key:'resource_trades',label:'资源交易'},{key:'insurance_policies',label:'保险策略'},{key:'memory_transfers',label:'记忆迁移'},{key:'edge_messages',label:'边缘消息'},{key:'public_audits',label:'公共审计'}]),trust=[{title:'证明网格',text:'跨组织证明支持阈值签名、依赖图与撤回传播。',state:'多方验证',type:'success',icon:Connection},{title:'后量子混合签名',text:'经典与 PQ 双签名覆盖身份、策略、证明和结算。',state:'迁移就绪',type:'warning',icon:Key},{title:'Agent 宪法运行时',text:'行为边界、群体表决和人类否决在执行前验证。',state:'强制门禁',type:'danger',icon:DocumentChecked}];async function load(){loading.value=true;try{Object.assign(overview,await planetaryResilienceApi.overview())}finally{loading.value=false}}async function runTwin(){if(domains.value.length<5){ElMessage.warning('联合演练必须覆盖五个基础设施域');return}try{const topology={'energy:grid':['communications:edge'],'communications:edge':['logistics:port'],'logistics:port':['finance:market'],'finance:market':['information:network']};const r=await planetaryResilienceApi.runTwin({domains:domains.value,topology,shocks:['energy:grid']});lastScore.value=r.systemic_score;ElMessage.success('联合冲击演练完成');await load()}catch{ElMessage.error('数字孪生运行失败')}}onMounted(load)</script>
<style scoped>.page{max-width:1260px;margin:auto;padding:28px 24px 48px}.page header{display:flex;justify-content:space-between;gap:24px;border-bottom:1px solid var(--el-border-color);padding-bottom:20px}.page h1{font-size:30px;margin:4px 0 6px;letter-spacing:0}.page header p{margin:0;color:var(--el-text-color-secondary)}.eyebrow{font-size:12px!important;color:var(--el-color-primary)!important;font-weight:700}.metrics{display:grid;grid-template-columns:repeat(10,1fr);margin-bottom:22px}.metrics>div{padding:16px 10px;border-bottom:1px solid var(--el-border-color);border-right:1px solid var(--el-border-color)}.metrics span{display:block;font-size:11px;color:var(--el-text-color-secondary)}.metrics strong{font-size:22px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--el-border-color);border:1px solid var(--el-border-color)}.grid article{background:var(--el-bg-color);padding:24px;min-height:185px}.grid .el-icon{font-size:25px;color:var(--el-color-primary)}.grid h2,.form h2{font-size:17px}.grid p{color:var(--el-text-color-secondary);line-height:1.6}.form{padding:14px 0}.form .el-checkbox-group{margin:20px 0}.result{margin-top:26px;border-block:1px solid var(--el-border-color);padding:18px 0}.result span{display:block;color:var(--el-text-color-secondary)}.result strong{font-size:30px}@media(max-width:900px){.metrics{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.page{padding:18px 14px}.page h1{font-size:25px}}</style>
